const products = [
            { id: 1, name: 'Wireless Headphones', price: 2499, oldPrice: 3999, image: 'data:image/jpeg;base64,' },
            { id: 2, name: 'Smart Watch Pro', price: 5999, oldPrice: 7999, image: 'data:image/jpeg;base64,' },
            { id: 3, name: 'Bluetooth Speaker', price: 1499, oldPrice: 2499, image: 'data:image/jpeg;base64,' },
            { id: 4, name: 'Laptop Backpack', price: 899, oldPrice: 1299, image: 'data:image/jpeg;base64,' },
            { id: 5, name: 'Mechanical Keyboard', price: 3499, oldPrice: 4999, image: 'data:image/jpeg;base64,' },
            { id: 6, name: 'Wireless Mouse', price: 799, oldPrice: 1199, image: 'data:image/jpeg;base64,' }
        ];

      
        let cart = JSON.parse(localStorage.getItem('cart')) || [];

        function saveCart() {
            localStorage.setItem('cart', JSON.stringify(cart));
            updateUI();
            renderProducts();
        }

        
        function renderProducts(filter = '') {
            const grid = document.getElementById('productGrid');
            const countEl = document.getElementById('productCount');
            let filtered = products;
            if (filter.trim() !== '') {
                const term = filter.toLowerCase().trim();
                filtered = products.filter(p => p.name.toLowerCase().includes(term));
            }
            countEl.textContent = filtered.length + ' items';

            if (filtered.length === 0) {
                grid.innerHTML = `<p style="grid-column:1/-1; text-align:center; padding:40px; color:#94a3b8;">No products found for "${filter}"</p>`;
                return;
            }

            grid.innerHTML = '';
            filtered.forEach(p => {
                const inCart = cart.find(item => item.id === p.id);
                const qty = inCart ? inCart.quantity : 0;
                const card = document.createElement('div');
                card.className = 'productCard';
                card.innerHTML = `
                    <img src="${p.image}" alt="${p.name}" loading="lazy" />
                    <div class="name">${p.name}</div>
                    <div class="price">₹${p.price.toLocaleString('en-IN')} ${p.oldPrice ? `<small>₹${p.oldPrice.toLocaleString('en-IN')}</small>` : ''}</div>
                    <button class="addBtn ${qty > 0 ? 'inCart' : ''}" data-id="${p.id}">${qty > 0 ? `✅ In Cart (${qty})` : '🛒 Add to Cart'}</button>
                `;
                grid.appendChild(card);
            });

            document.querySelectorAll('.addBtn').forEach(btn => {
                btn.addEventListener('click', function() {
                    const id = parseInt(this.dataset.id);
                    addToCart(id);
                });
            });
        }

      
        function addToCart(id) {
            const product = products.find(p => p.id === id);
            if (!product) return;
            const existing = cart.find(item => item.id === id);
            if (existing) {
                existing.quantity += 1;
                showToast(`➕ ${product.name} qty increased`, 'success');
            } else {
                cart.push({ id: product.id, name: product.name, price: product.price, image: product.image, quantity: 1 });
                showToast(`✅ ${product.name} added!`, 'success');
            }
            saveCart();
        }

      
        function updateUI() {
            const totalItems = cart.reduce((s, i) => s + i.quantity, 0);
            document.getElementById('badge').textContent = totalItems;
            document.getElementById('mobileBadge').textContent = totalItems;

            if (cart.length === 0) {
                document.getElementById('cartItems').innerHTML = `<div class="cartEmpty"><span>🛍️</span>Cart is empty</div>`;
                document.getElementById('cartTotal').textContent = '₹0.00';
                return;
            }

            let html = '';
            let total = 0;
            cart.forEach(item => {
                const sub = item.price * item.quantity;
                total += sub;
                html += `
                    <div class="cartItem">
                        <img src="${item.image}" alt="${item.name}" />
                        <div class="info">
                            <div class="itemName">${item.name}</div>
                            <div class="itemPrice">₹${item.price.toLocaleString('en-IN')}</div>
                            <div class="controls">
                                <button onclick="changeQty(${item.id}, -1)">−</button>
                                <span class="qty">${item.quantity}</span>
                                <button onclick="changeQty(${item.id}, 1)">+</button>
                                <button class="removeBtn" onclick="removeItem(${item.id})">✕</button>
                            </div>
                        </div>
                    </div>
                `;
            });
            document.getElementById('cartItems').innerHTML = html;
            document.getElementById('cartTotal').textContent = `₹${total.toLocaleString('en-IN')}`;
        }

        function changeQty(id, delta) {
            const item = cart.find(i => i.id === id);
            if (!item) return;
            item.quantity += delta;
            if (item.quantity <= 0) {
                cart = cart.filter(i => i.id !== id);
            }
            saveCart();
        }

        function removeItem(id) {
            cart = cart.filter(i => i.id !== id);
            saveCart();
            showToast('🗑️ Item removed', 'error');
        }

        function clearCart() {
            if (cart.length === 0) { showToast('Cart is empty', 'error'); return; }
            cart = [];
            saveCart();
            showToast('🧹 Cart cleared', 'error');
        }

        function checkout() {
            if (cart.length === 0) { showToast('Cart is empty!', 'error'); return; }
            const total = cart.reduce((s, i) => s + i.price * i.quantity, 0);
            showToast(`🎉 Order placed! Total: ₹${total.toLocaleString('en-IN')}`, 'success');
            cart = [];
            saveCart();
            closeCart();
        }

        
        function openCart() {
            document.getElementById('cartSidebar').classList.add('open');
            document.getElementById('cartOverlay').classList.add('open');
            document.body.style.overflow = 'hidden';
        }

        function closeCart() {
            document.getElementById('cartSidebar').classList.remove('open');
            document.getElementById('cartOverlay').classList.remove('open');
            document.body.style.overflow = '';
        }

        let slideIndex = 0;
        const totalSlides = 3;
        const track = document.getElementById('track');
        const dotEls = document.querySelectorAll('#dots span');

        function updateCarousel() {
            track.style.transform = `translateX(-${slideIndex * 100}%)`;
            dotEls.forEach((d, i) => d.classList.toggle('active', i === slideIndex));
        }

        function nextSlide() { slideIndex = (slideIndex + 1) % totalSlides; updateCarousel(); }
        function prevSlide() { slideIndex = (slideIndex - 1 + totalSlides) % totalSlides; updateCarousel(); }
        function goSlide(i) { slideIndex = i; updateCarousel(); }

        let autoSlide = setInterval(nextSlide, 4500);
        document.getElementById('carousel').addEventListener('mouseenter', () => clearInterval(autoSlide));
        document.getElementById('carousel').addEventListener('mouseleave', () => {
            autoSlide = setInterval(nextSlide, 4500);
        });

       
        function showProductDropdown() {
            const dropdown = document.getElementById('productDropdown');
            if (dropdown.children.length === 0) {
                dropdown.innerHTML = products.map(p => `
                    <div class="item" onclick="selectProduct(${p.id})">
                        <img src="${p.image}" alt="${p.name}" />
                        <span class="name">${p.name}</span>
                        <span class="price">₹${p.price}</span>
                    </div>
                `).join('');
            }
            dropdown.style.display = 'block';
        }

        function hideProductDropdown() {
            document.getElementById('productDropdown').style.display = 'none';
        }

        function selectProduct(id) {
            const product = products.find(p => p.id === id);
            if (product) {
                renderProducts(product.name);
                hideProductDropdown();
                document.querySelector('.container').scrollIntoView({ behavior: 'smooth' });
                
                document.getElementById('searchInput').value = product.name;
            }
        }

      
        const searchInput = document.getElementById('searchInput');
        const searchDropdown = document.getElementById('searchDropdown');

        searchInput.addEventListener('input', function() {
            const term = this.value.trim();
            if (term === '') {
                searchDropdown.style.display = 'none';
                return;
            }
            const filtered = products.filter(p => p.name.toLowerCase().includes(term.toLowerCase()));
            if (filtered.length === 0) {
                searchDropdown.innerHTML = `<div class="no-result">No products found</div>`;
                searchDropdown.style.display = 'block';
                return;
            }
            searchDropdown.innerHTML = filtered.map(p => `
                <div class="item" onclick="selectProduct(${p.id})">
                    <img src="${p.image}" alt="${p.name}" />
                    <span class="name">${p.name}</span>
                    <span class="price">₹${p.price}</span>
                </div>
            `).join('');
            searchDropdown.style.display = 'block';
        });

     
        document.addEventListener('click', function(e) {
            if (!document.querySelector('.search-box').contains(e.target)) {
                searchDropdown.style.display = 'none';
            }
            
            if (!document.querySelector('#navLinks').contains(e.target)) {
                hideProductDropdown();
            }
        });

        function toggleMenu() {
            document.getElementById('mobileMenu').classList.toggle('open');
        }

        
        function goHome() {
            window.scrollTo({ top: 0, behavior: 'smooth' });
        }

      
        function handleSearch(e) {
            e.preventDefault();
            const term = document.getElementById('searchInput').value.trim() ||
                         document.getElementById('mobileSearchInput').value.trim();
            renderProducts(term);
            document.getElementById('searchInput').value = '';
            document.getElementById('mobileSearchInput').value = '';
            searchDropdown.style.display = 'none';
        }

        
        let authMode = 'login';

        function openAuth(mode = 'login') {
            authMode = mode;
            const modal = document.getElementById('authModal');
            const title = document.getElementById('authTitle');
            const submitBtn = document.getElementById('authSubmitBtn');
            const switchText = document.getElementById('authSwitchText');
            const switchLink = document.getElementById('authSwitchLink');
            const regFields = document.getElementById('registerFields');
            const authFields = document.getElementById('authFields');

            if (mode === 'login') {
                title.textContent = 'Account Login';
                submitBtn.textContent = 'Sign In';
                switchText.textContent = "Don't have an account?";
                switchLink.textContent = 'Sign Up';
                regFields.style.display = 'none';
                authFields.style.display = 'block';
            } else {
                title.textContent = 'Create Account';
                submitBtn.textContent = 'Sign Up';
                switchText.textContent = 'Already have an account?';
                switchLink.textContent = 'Sign In';
                regFields.style.display = 'block';
                authFields.style.display = 'block';
            }
            modal.classList.add('open');
            document.body.style.overflow = 'hidden';
        }

        function closeAuth() {
            document.getElementById('authModal').classList.remove('open');
            document.body.style.overflow = '';
        }

        function toggleAuth() {
            authMode = authMode === 'login' ? 'register' : 'login';
            openAuth(authMode);
        }

        function handleAuth(e) {
            e.preventDefault();
            const email = document.getElementById('authEmail').value.trim();
            const password = document.getElementById('authPassword').value.trim();

            if (authMode === 'login') {
                const stored = localStorage.getItem('user');
                if (!stored) {
                    showToast('❌ No account found. Please sign up first.', 'error');
                    return;
                }
                const user = JSON.parse(stored);
                if (email === user.email && password === user.password) {
                    showToast(`🎉 Welcome back, ${user.name || 'User'}!`, 'success');
                    closeAuth();
                    updateNavForUser(user.name);
                } else {
                    showToast('❌ Invalid credentials. Try again.', 'error');
                }
            } else {
                const name = document.getElementById('regName').value.trim();
                const confirm = document.getElementById('regConfirm').value.trim();
                if (!name) { showToast('Please enter your full name.', 'error'); return; }
                if (password !== confirm) { showToast('❌ Passwords do not match.', 'error'); return; }
                if (password.length < 6) { showToast('❌ Password must be at least 6 characters.', 'error'); return; }
                const terms = document.getElementById('regTerms').checked;
                if (!terms) { showToast('Please agree to the Terms.', 'error'); return; }

                const user = { name, email, password };
                localStorage.setItem('user', JSON.stringify(user));
                showToast(`✅ Account created! Welcome ${name}!`, 'success');
                closeAuth();
                updateNavForUser(name);
                authMode = 'login';
            }
            document.getElementById('authForm').reset();
        }

        function updateNavForUser(name) {
            const links = document.querySelectorAll('#authNavLink, #mobileAuthLink');
            links.forEach(link => {
                link.textContent = `👤 ${name}`;
                link.style.color = '#22c55e';
                link.onclick = () => {
                    if (confirm(`Log out ${name}?`)) {
                        localStorage.removeItem('user');
                        location.reload();
                    }
                };
            });
        }

        document.getElementById('authModal').addEventListener('click', function(e) {
            if (e.target === this) closeAuth();
        });

       
        document.addEventListener('keydown', function(e) {
            if (e.key === 'Escape') { closeCart(); closeAuth(); }
        });

       
        let toastEl = document.getElementById('toast');
        let toastTimer;

        function showToast(msg, type = 'success') {
            toastEl.textContent = msg;
            toastEl.className = 'toast ' + type;
            void toastEl.offsetWidth;
            toastEl.classList.add('show');
            clearTimeout(toastTimer);
            toastTimer = setTimeout(() => toastEl.classList.remove('show'), 2500);
        }

      
        renderProducts('');
        updateUI();
        updateCarousel();

        const storedUser = localStorage.getItem('user');
        if (storedUser) {
            const user = JSON.parse(storedUser);
            updateNavForUser(user.name);
        }

        console.log('🛍️ MyStore ready! Products dropdown with names, live search, cart, auth working.');
   